def run(program: str) -> list[str]:
    stack = []
    output = []
    lines = [line.strip() for line in program.split('\n') if line.strip() and not line.startswith('#')]
    for i, line in enumerate(lines, 1):
        parts = line.split()
        if not parts:
            continue
        cmd = parts[0]
        try:
            if cmd == 'PUSH':
                n = int(parts[1])
                stack.append(n)
            elif cmd == 'POP':
                if len(stack) == 0:
                    raise ValueError(f"Stack underflow at line {i}")
                stack.pop()
            elif cmd == 'ADD':
                if len(stack) < 2:
                    raise ValueError(f"Not enough values for ADD at line {i}")
                a, b = stack.pop(), stack.pop()
                stack.append(a + b)
            elif cmd == 'SUB':
                if len(stack) < 2:
                    raise ValueError(f"Not enough values for SUB at line {i}")
                a, b = stack.pop(), stack.pop()
                stack.append(b - a)
            elif cmd == 'MUL':
                if len(stack) < 2:
                    raise ValueError(f"Not enough values for MUL at line {i}")
                a, b = stack.pop(), stack.pop()
                stack.append(a * b)
            elif cmd == 'DIV':
                if len(stack) < 2:
                    raise ValueError(f"Not enough values for DIV at line {i}")
                a, b = stack.pop(), stack.pop()
                if b == 0:
                    raise ZeroDivisionError(f"Division by zero at line {i}")
                stack.append(a // b)
            elif cmd == 'DUP':
                if len(stack) == 0:
                    raise ValueError(f"Not enough values for DUP at line {i}")
                stack.append(stack[-1])
            elif cmd == 'SWAP':
                if len(stack) < 2:
                    raise ValueError(f"Not enough values for SWAP at line {i}")
                a, b = stack.pop(), stack.pop()
                stack.append(a)
                stack.append(b)
            elif cmd == 'PRINT':
                if len(stack) == 0:
                    raise ValueError(f"No value to print at line {i}")
                output.append(str(stack[-1]))
        except (ValueError, ZeroDivisionError) as e:
            raise e
    return output
